window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-csat.html"]="<!-- Settings: CSAT -->\n<style>\n.csat-toggle-bar{display:flex;align-items:center;gap:12px;padding:16px;background:var(--card);border:1px solid var(--border);border-radius:8px;margin-bottom:20px}\n.csat-toggle-bar .label{flex:1;font-weight:700;font-size:14px}\n.csat-toggle-bar .sub{font-size:12px;color:var(--muted)}\n.toggle{position:relative;width:40px;height:22px;cursor:pointer}\n.toggle input{opacity:0;width:0;height:0}\n.toggle .slider{position:absolute;inset:0;background:#ccc;border-radius:22px;transition:.2s}\n.toggle .slider:before{content:'';position:absolute;width:16px;height:16px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s}\n.toggle input:checked+.slider{background:var(--accent)}\n.toggle input:checked+.slider:before{transform:translateX(18px)}\n.csat-form{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:20px;max-width:520px}\n.csat-form label{display:block;margin-bottom:14px;font-size:13px;font-weight:600}\n.csat-form input,.csat-form select{width:100%;margin-top:4px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg)}\n.csat-preview{margin-top:20px;padding:20px;background:var(--bg);border-radius:8px;text-align:center}\n.csat-preview .q{font-size:15px;font-weight:600;margin-bottom:12px}\n.csat-preview .scale{display:flex;justify-content:center;gap:8px}\n.csat-preview .dot{width:36px;height:36px;border-radius:50%;background:var(--card);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;cursor:default}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">⏱️ SLA</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">⚡ Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">🟢 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">🔵 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">💬 Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin:0 0 4px\">⭐ CSAT (Customer Satisfaction)</h2>\n    <p style=\"color:var(--muted);font-size:13px;margin:0 0 20px\">Konfigurasi survei kepuasan pelanggan setelah percakapan selesai.</p>\n\n    <div class=\"csat-toggle-bar\">\n      <div>\n        <div class=\"label\">Aktifkan CSAT</div>\n        <div class=\"sub\">Kirim survei otomatis saat percakapan ditutup</div>\n      </div>\n      <label class=\"toggle\"><input type=\"checkbox\" id=\"csatEnabled\" onchange=\"updatePreview();saveCsat()\"><span class=\"slider\"></span></label>\n    </div>\n\n    <div class=\"csat-form\" id=\"csatForm\">\n      <label>Pertanyaan survei\n        <input id=\"csatQuestion\" placeholder=\"Bagaimana pengalaman layanan kami?\" oninput=\"updatePreview();saveCsat()\">\n      </label>\n      <label>Skala penilaian\n        <select id=\"csatScale\" onchange=\"updatePreview();saveCsat()\">\n          <option value=\"1-5\">1 - 5 (Bintang)</option>\n          <option value=\"1-3\">1 - 3 (Buruk/Netral/Baik)</option>\n          <option value=\"1-10\">1 - 10 (NPS)</option>\n        </select>\n      </label>\n    </div>\n\n    <h3 style=\"margin:20px 0 8px;font-size:14px\">Preview Survei</h3>\n    <div class=\"csat-preview\" id=\"csatPreview\">\n      <div class=\"q\" id=\"prevQ\">-</div>\n      <div class=\"scale\" id=\"prevScale\"></div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const csat = DB.settings.csat;\n  document.getElementById('csatEnabled').checked = csat.enabled;\n  document.getElementById('csatQuestion').value = csat.question;\n  document.getElementById('csatScale').value = csat.scale;\n  updatePreview();\n})();\n\nfunction updatePreview(){\n  const q = document.getElementById('csatQuestion').value || 'Bagaimana pengalaman layanan kami?';\n  const scale = document.getElementById('csatScale').value;\n  document.getElementById('prevQ').textContent = q;\n  const [lo,hi] = scale.split('-').map(Number);\n  let html = '';\n  for(let i=lo;i<=hi;i++) html += `<div class=\"dot\">${i}</div>`;\n  document.getElementById('prevScale').innerHTML = html;\n  document.getElementById('csatForm').style.opacity = document.getElementById('csatEnabled').checked ? 1 : 0.4;\n}\n\nfunction saveCsat(){\n  DB.settings.csat = {\n    enabled: document.getElementById('csatEnabled').checked,\n    question: document.getElementById('csatQuestion').value,\n    scale: document.getElementById('csatScale').value,\n  };\n  saveStore();\n  showToast('Pengaturan CSAT disimpan');\n}\n</script>\n";
